-- Varied, server-graded lesson activities: ordering, fill-in with word bank and find-the-error.
-- Source: docs/curriculum/varied-activities.json. Additive; on conflict do nothing.
-- For order_steps the answer is exercise_solutions.correct_sequence; correct_answer keeps its
-- A-D check and stores the first step. Requires 20261010110000 (correct_sequence column).
create temp table _v(lesson text,slug text,kind text,prompt text,options jsonb,explanation text,answer text,seq text) on commit drop;
do $$begin if (select count(*) from _v v join public.lessons l on l.slug=v.lesson)<>30 then raise exception 'lesson missing'; end if; end$$;
 select l.id,v.slug,v.prompt,v.kind,v.options,v.explanation,(select coalesce(max(e.sort_order),0)+1 from public.exercises e where e.lesson_id=l.id),'published'
 from _v v join public.lessons l on l.slug=v.lesson on conflict(slug) do nothing;
 select e.id,v.answer,v.seq from _v v join public.exercises e on e.slug=v.slug on conflict(exercise_id) do nothing;
